const raw = $input.first().json;

function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

function firstNonBlank(...values) {
  for (const value of values) {
    if (value === null || value === undefined) continue;
    if (typeof value === 'string') {
      const trimmed = value.trim();
      if (trimmed) return trimmed;
      continue;
    }
    if (typeof value === 'number' || typeof value === 'boolean') {
      return String(value);
    }
  }
  return null;
}

function safeJson(value, maxLength = 2000) {
  try {
    const rendered = typeof value === 'string' ? value : JSON.stringify(value);
    if (!rendered) return null;
    return rendered.length > maxLength ? `${rendered.slice(0, maxLength)}...` : rendered;
  } catch (error) {
    return '[unserializable payload]';
  }
}

const execution = raw.execution || {};
const executionError = execution.error || {};
const rawError = raw.error || {};

const workflowName = firstNonBlank(
  raw.workflow?.name,
  raw.workflowName,
  raw.workflow?.id,
  'unknown-workflow',
);
const nodeName = firstNonBlank(
  execution.lastNodeExecuted,
  execution.lastNode,
  executionError.node?.name,
  executionError.nodeName,
  raw.lastNodeExecuted,
  raw.node?.name,
  raw.nodeName,
  rawError.node?.name,
  rawError.nodeName,
  raw.context?.node_name,
  'unknown-node',
);
const errorMsg = firstNonBlank(
  executionError.message,
  executionError.description,
  executionError.cause?.message,
  typeof execution.error === 'string' ? execution.error : null,
  rawError.message,
  rawError.description,
  rawError.cause?.message,
  typeof raw.error === 'string' ? raw.error : null,
  raw.message,
  raw.description,
  'unknown error',
);
const errorStack = firstNonBlank(executionError.stack, rawError.stack);
const rawPayloadSample =
  nodeName === 'unknown-node' || errorMsg === 'unknown error' ? safeJson(raw) : undefined;

const step = nodeName;
const incident_key = `${workflowName}:${nodeName}:${String(errorMsg).slice(0, 60).replace(/\s+/g, '-').toLowerCase()}`;

return [
  {
    json: {
      incident_id: uuidv4(),
      incident_key,
      severity: 'high',
      source: `n8n-error:${workflowName}`,
      step,
      timestamp: new Date().toISOString(),
      summary: `n8n workflow failed: ${workflowName} at node ${nodeName}`,
      error: errorMsg,
      context: {
        workflow_id: raw.workflow?.id,
        workflow_name: workflowName,
        execution_id: execution.id,
        execution_url: execution.url,
        node_name: nodeName,
        mode: execution.mode,
        error_description: firstNonBlank(executionError.description, rawError.description),
        error_stack: errorStack ? safeJson(errorStack) : undefined,
        raw_payload_sample: rawPayloadSample,
      },
    },
  },
];
